// board VFX volume instead of the lamp, so the anchor is gone).

using UnityEngine;

/// <summary>
/// Board lamp for the ball save: lit while losing the ball in play would return it to the
/// launcher, off the rest of the time. Swaps authored materials the same way the Abductor's
/// progress lights do, rather than tinting through a <see cref="BoardLight"/> property block.
/// </summary>
[DisallowMultipleComponent]
public sealed class BallSaveLight : MonoBehaviour
{
    [Header("Lamp")]
    [Tooltip("Renderers swapped between the off and on materials. Left empty, the first " +
             "renderer on this object or its children is used.")]
    [SerializeField] private Renderer[] lightRenderers;

    [Tooltip("Material worn while the ball save is not running — the grey/off look.")]
    [SerializeField] private Material offMaterial;

    [Tooltip("Material worn while the ball save is running — the lit look.")]
    [SerializeField] private Material onMaterial;

    private DrainHandler drainHandler;
    private bool isLit;
    private bool hasApplied;

    private void Awake()
    {
        ResolveRenderersIfNeeded();
        ServiceLocator.Register(this);
    }

    private void OnDestroy()
    {
        if (ServiceLocator.Get<BallSaveLight>() == this)
        {
            ServiceLocator.Unregister<BallSaveLight>();
        }
    }

    private void OnEnable()
    {
        ApplyLit(false);
    }

    private void Update()
    {
        if (drainHandler == null)
        {
            drainHandler = ServiceLocator.Get<DrainHandler>();
        }

        ApplyLit(drainHandler != null && drainHandler.IsBallSaveArmed);
    }

    private void ResolveRenderersIfNeeded()
    {
        if (lightRenderers != null && lightRenderers.Length > 0)
        {
            return;
        }

        Renderer own = GetComponentInChildren<Renderer>(true);
        lightRenderers = own != null
            ? new[] { own }
            : System.Array.Empty<Renderer>();
    }

    /// <summary>Materials are only written on a state flip, so the steady case costs nothing.</summary>
    private void ApplyLit(bool lit)
    {
        if (hasApplied && lit == isLit)
        {
            return;
        }

        isLit = lit;
        hasApplied = true;

        Material material = lit ? onMaterial : offMaterial;
        if (material == null || lightRenderers == null)
        {
            return;
        }

        for (int i = 0; i < lightRenderers.Length; i++)
        {
            // sharedMaterial, not material: these are authored assets being pointed at,
            // so there is nothing to instance and nothing to leak.
            if (lightRenderers[i] != null)
            {
                lightRenderers[i].sharedMaterial = material;
            }
        }
    }
}
